-- atto1 initial data model for Cloudflare D1 (SQLite), ADR-005. Ports the Postgres
-- schema from ADR-003 (supabase/migrations/20261007000000_initial_data_model.sql).
--
-- Units: distance in whole km, energy in kWh, money in integer minor units (cents)
-- plus an ISO 4217 currency code, temperature in degrees Celsius, state of charge as
-- a 0-100 percentage.
--
-- SQLite has no uuid, timestamptz, enum, boolean or array types, so:
--   * ids are lower-case uuid-v4 text, generated by the default below;
--   * instants are ISO 8601 UTC text ('2026-10-07T01:00:00.000Z'), calendar days are
--     'YYYY-MM-DD' text, both checked with julianday()/date();
--   * enums are text with a CHECK ... IN (...);
--   * booleans are 0/1 integers (the Worker maps them back to booleans);
--   * notes.tags is a JSON array of non-empty strings.
-- Tables are STRICT, so an integer column rejects 21.5 as the Postgres column did.
--
-- Ownership: there is no row-level security. Every row carries user_id, the Cloudflare
-- Access subject the Worker verified, and the Worker scopes every query by it. Child
-- tables reference vehicles through (vehicle_id, user_id), so a row can never point at
-- another user's vehicle even through a buggy Worker query.

-- vehicles ------------------------------------------------------------------

create table vehicles (
  id text primary key not null default (
    lower(hex(randomblob(4))) || '-' || lower(hex(randomblob(2))) || '-4' ||
    substr(lower(hex(randomblob(2))), 2) || '-' || substr('89ab', abs(random()) % 4 + 1, 1) ||
    substr(lower(hex(randomblob(2))), 2) || '-' || lower(hex(randomblob(6)))
  ),
  user_id text not null check (length(user_id) between 1 and 200),
  nickname text not null check (length(trim(nickname)) between 1 and 80),
  vin text check (length(vin) = 17 and vin not glob '*[^A-HJ-NPR-Z0-9]*'),
  model_year integer check (model_year between 2020 and 2100),
  variant text check (length(variant) <= 80),
  battery_capacity_kwh real check (battery_capacity_kwh > 0),
  purchased_on text check (date(purchased_on) is purchased_on),
  created_at text not null default (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) check (julianday(created_at) is not null),
  updated_at text not null default (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) check (julianday(updated_at) is not null),
  unique (id, user_id),
  unique (user_id, vin)
) strict;

create index vehicles_user_id_idx on vehicles (user_id);

-- charging_sessions ---------------------------------------------------------

create table charging_sessions (
  id text primary key not null default (
    lower(hex(randomblob(4))) || '-' || lower(hex(randomblob(2))) || '-4' ||
    substr(lower(hex(randomblob(2))), 2) || '-' || substr('89ab', abs(random()) % 4 + 1, 1) ||
    substr(lower(hex(randomblob(2))), 2) || '-' || lower(hex(randomblob(6)))
  ),
  user_id text not null check (length(user_id) between 1 and 200),
  vehicle_id text not null,
  started_at text not null check (julianday(started_at) is not null),
  ended_at text check (ended_at is null or coalesce(julianday(ended_at) > julianday(started_at), 0)),
  energy_kwh real not null check (energy_kwh > 0),
  cost_cents integer check (cost_cents >= 0),
  currency text not null default 'AUD' check (length(currency) = 3 and currency not glob '*[^A-Z]*'),
  charger_type text not null check (charger_type in ('ac_home', 'ac_public', 'dc_fast')),
  location_name text check (length(location_name) <= 200),
  start_soc_pct integer check (start_soc_pct between 0 and 100),
  end_soc_pct integer check (end_soc_pct between 0 and 100),
  odometer_km integer check (odometer_km >= 0),
  notes text,
  created_at text not null default (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) check (julianday(created_at) is not null),
  updated_at text not null default (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) check (julianday(updated_at) is not null),
  check (end_soc_pct >= start_soc_pct),
  foreign key (vehicle_id, user_id) references vehicles (id, user_id) on delete cascade
) strict;

create index charging_sessions_vehicle_started_idx on charging_sessions (vehicle_id, started_at desc);
create index charging_sessions_user_id_idx on charging_sessions (user_id);

-- range_observations --------------------------------------------------------

create table range_observations (
  id text primary key not null default (
    lower(hex(randomblob(4))) || '-' || lower(hex(randomblob(2))) || '-4' ||
    substr(lower(hex(randomblob(2))), 2) || '-' || substr('89ab', abs(random()) % 4 + 1, 1) ||
    substr(lower(hex(randomblob(2))), 2) || '-' || lower(hex(randomblob(6)))
  ),
  user_id text not null check (length(user_id) between 1 and 200),
  vehicle_id text not null,
  observed_at text not null default (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) check (julianday(observed_at) is not null),
  soc_pct integer not null check (soc_pct between 0 and 100),
  displayed_range_km integer not null check (displayed_range_km >= 0),
  odometer_km integer check (odometer_km >= 0),
  outside_temp_c real check (outside_temp_c between -50 and 60),
  climate_on integer check (climate_on in (0, 1)),
  notes text,
  created_at text not null default (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) check (julianday(created_at) is not null),
  updated_at text not null default (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) check (julianday(updated_at) is not null),
  foreign key (vehicle_id, user_id) references vehicles (id, user_id) on delete cascade
) strict;

create index range_observations_vehicle_observed_idx on range_observations (vehicle_id, observed_at desc);
create index range_observations_user_id_idx on range_observations (user_id);

-- vehicle_features ----------------------------------------------------------

create table vehicle_features (
  id text primary key not null default (
    lower(hex(randomblob(4))) || '-' || lower(hex(randomblob(2))) || '-4' ||
    substr(lower(hex(randomblob(2))), 2) || '-' || substr('89ab', abs(random()) % 4 + 1, 1) ||
    substr(lower(hex(randomblob(2))), 2) || '-' || lower(hex(randomblob(6)))
  ),
  user_id text not null check (length(user_id) between 1 and 200),
  vehicle_id text not null,
  category text not null check (category in (
    'battery', 'charging', 'performance', 'dimensions', 'safety',
    'driver_assistance', 'infotainment', 'comfort', 'other'
  )),
  name text not null check (length(trim(name)) between 1 and 120),
  value text not null check (length(trim(value)) between 1 and 500),
  unit text check (length(unit) <= 20),
  manual_reference text check (length(manual_reference) <= 200),
  notes text,
  created_at text not null default (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) check (julianday(created_at) is not null),
  updated_at text not null default (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) check (julianday(updated_at) is not null),
  unique (vehicle_id, category, name),
  foreign key (vehicle_id, user_id) references vehicles (id, user_id) on delete cascade
) strict;

create index vehicle_features_user_id_idx on vehicle_features (user_id);

-- maintenance_records -------------------------------------------------------

create table maintenance_records (
  id text primary key not null default (
    lower(hex(randomblob(4))) || '-' || lower(hex(randomblob(2))) || '-4' ||
    substr(lower(hex(randomblob(2))), 2) || '-' || substr('89ab', abs(random()) % 4 + 1, 1) ||
    substr(lower(hex(randomblob(2))), 2) || '-' || lower(hex(randomblob(6)))
  ),
  user_id text not null check (length(user_id) between 1 and 200),
  vehicle_id text not null,
  performed_on text not null check (date(performed_on) is performed_on),
  category text not null check (category in (
    'scheduled_service', 'tyres', 'repair', 'recall', 'inspection', 'software_update', 'other'
  )),
  title text not null check (length(trim(title)) between 1 and 200),
  description text,
  provider text check (length(provider) <= 200),
  odometer_km integer check (odometer_km >= 0),
  cost_cents integer check (cost_cents >= 0),
  currency text not null default 'AUD' check (length(currency) = 3 and currency not glob '*[^A-Z]*'),
  next_due_on text check (date(next_due_on) is next_due_on and next_due_on >= performed_on),
  next_due_km integer check (next_due_km >= 0),
  created_at text not null default (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) check (julianday(created_at) is not null),
  updated_at text not null default (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) check (julianday(updated_at) is not null),
  check (next_due_km >= odometer_km),
  foreign key (vehicle_id, user_id) references vehicles (id, user_id) on delete cascade
) strict;

create index maintenance_records_vehicle_performed_idx on maintenance_records (vehicle_id, performed_on desc);
create index maintenance_records_user_id_idx on maintenance_records (user_id);

-- notes ---------------------------------------------------------------------

create table notes (
  id text primary key not null default (
    lower(hex(randomblob(4))) || '-' || lower(hex(randomblob(2))) || '-4' ||
    substr(lower(hex(randomblob(2))), 2) || '-' || substr('89ab', abs(random()) % 4 + 1, 1) ||
    substr(lower(hex(randomblob(2))), 2) || '-' || lower(hex(randomblob(6)))
  ),
  user_id text not null check (length(user_id) between 1 and 200),
  vehicle_id text,
  title text not null check (length(trim(title)) between 1 and 200),
  body text not null default '',
  -- A JSON array of non-empty strings: an empty string would encode as "".
  tags text not null default '[]' check (json_valid(tags) and json_type(tags) = 'array' and instr(tags, '""') = 0),
  pinned integer not null default 0 check (pinned in (0, 1)),
  created_at text not null default (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) check (julianday(created_at) is not null),
  updated_at text not null default (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) check (julianday(updated_at) is not null),
  foreign key (vehicle_id, user_id) references vehicles (id, user_id)
) strict;

create index notes_user_updated_idx on notes (user_id, updated_at desc);
create index notes_vehicle_id_idx on notes (vehicle_id);

-- Deleting a vehicle keeps its notes; only vehicle_id is cleared. SQLite cannot name
-- the column to null in a composite foreign key (Postgres's `set null (vehicle_id)`),
-- and a plain SET NULL would also null the not-null user_id, so a trigger detaches them.
create trigger vehicles_detach_notes before delete on vehicles
for each row
begin
  update notes set vehicle_id = null where vehicle_id = old.id;
end;

-- updated_at triggers -------------------------------------------------------
-- Bump updated_at on any update that did not set it itself. The guard also stops the
-- trigger's own update from re-firing it.

create trigger vehicles_set_updated_at after update on vehicles
for each row when new.updated_at = old.updated_at
begin
  update vehicles set updated_at = strftime('%Y-%m-%dT%H:%M:%fZ', 'now') where id = new.id;
end;

create trigger charging_sessions_set_updated_at after update on charging_sessions
for each row when new.updated_at = old.updated_at
begin
  update charging_sessions set updated_at = strftime('%Y-%m-%dT%H:%M:%fZ', 'now') where id = new.id;
end;

create trigger range_observations_set_updated_at after update on range_observations
for each row when new.updated_at = old.updated_at
begin
  update range_observations set updated_at = strftime('%Y-%m-%dT%H:%M:%fZ', 'now') where id = new.id;
end;

create trigger vehicle_features_set_updated_at after update on vehicle_features
for each row when new.updated_at = old.updated_at
begin
  update vehicle_features set updated_at = strftime('%Y-%m-%dT%H:%M:%fZ', 'now') where id = new.id;
end;

create trigger maintenance_records_set_updated_at after update on maintenance_records
for each row when new.updated_at = old.updated_at
begin
  update maintenance_records set updated_at = strftime('%Y-%m-%dT%H:%M:%fZ', 'now') where id = new.id;
end;

create trigger notes_set_updated_at after update on notes
for each row when new.updated_at = old.updated_at
begin
  update notes set updated_at = strftime('%Y-%m-%dT%H:%M:%fZ', 'now') where id = new.id;
end;
